import fs from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { ROOT, expectedFiles, renderAgent } from "./sync-agents";

describe("renderAgent", () => {
  it("joins frontmatter, the generated-file header, body and extra", () => {
    const out = renderAgent({ role: "x", frontmatter: "name: x\n", body: "Body.\n\n", extra: "Extra.\n" });
    expect(out).toBe(
      "---\nname: x\n---\n\n" +
        "<!-- Generated by scripts/sync-agents.ts from agents/roles/x/. Edit there, then run npm run agents:sync. -->\n\n" +
        "Body.\n\nExtra.\n",
    );
  });

  it("leaves out a missing extra", () => {
    expect(renderAgent({ role: "x", frontmatter: "a: 1", body: "B" }).endsWith("-->\n\nB\n")).toBe(true);
  });
});

describe("generated agent files", () => {
  const files = expectedFiles();

  it("covers every role for both tools", () => {
    const roles = fs
      .readdirSync(path.join(ROOT, "agents", "roles"), { withFileTypes: true })
      .filter((d) => d.isDirectory())
      .map((d) => d.name);
    expect(roles.length).toBeGreaterThan(0);
    const expected = roles.flatMap((r) => [`.claude/agents/${r}.md`, `.omp/agents/${r}.md`]).sort();
    expect(files.map((f) => f.relPath).sort()).toEqual(expected);
  });

  it("has no agent files without a role source", () => {
    const expected = new Set(files.map((f) => f.relPath));
    const onDisk = [".claude/agents", ".omp/agents"].flatMap((dir) =>
      fs.existsSync(path.join(ROOT, dir))
        ? fs.readdirSync(path.join(ROOT, dir)).filter((n) => n.endsWith(".md")).map((n) => `${dir}/${n}`)
        : [],
    );
    expect(onDisk.filter((p) => !expected.has(p))).toEqual([]);
  });

  for (const file of files) {
    it(`${file.relPath} matches agents/roles/${file.role}/`, () => {
      const target = path.join(ROOT, file.relPath);
      const committed = fs.existsSync(target) ? fs.readFileSync(target, "utf8") : null;
      expect(
        committed === file.content,
        `${file.relPath} is out of date with agents/roles/${file.role}/: run npm run agents:sync`,
      ).toBe(true);
    });
  }
});
